insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$itapeva$q$, $q$https://www.itapeva.sp.leg.br/legislacao/3118-lei-3052-2010 ; https://www.itapeva.sp.leg.br/legislacao/1563-lei-1590-2000 ; https://www.itapeva.sp.leg.br/legislacao/2530-lei-2498-2006 ; https://www.itapeva.sp.leg.br/legislacao/3117-lei-3051-2010 ; https://www.itapeva.sp.leg.br/legislacao/3005-lei-2940-2009$q$, $q$Atos oficiais de Itapeva: domínio público (Lei 9.610/1998 art. 8º IV). Área central: OpenStreetMap (ODbL 1.0, © colaboradores do OSM). Vias urbanas: IBGE, Malha de Setores Censitários do Censo 2022 (dados públicos, citar a fonte: IBGE), com as rodovias recortadas sobre o OpenStreetMap (ODbL 1.0).$q$, 4, $q$Lei 1.590/2000 (red. Lei 3.052/2010): área central, veículos com capacidade de carga acima de 4 t só para carga e descarga das 19h às 10h e aos sábados após as 15h (duas regras: horário proibido e passagem). Lei 2.498/2006 (red. Lei 3.051/2010): caminhões proibidos nas vias urbanas, salvo carga e descarga e exceções. Lei 1.027/1997 revogada; Lei 2.940/2009 (escolas) desativada.$q$);
